const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const clinic_name = text(input.clinic_name);
const doctor_name = text(input.doctor_name);
const start_date = text(input.start_date);
const start_time = text(input.start_time);
const end_date = text(input.end_date);
const end_time = text(input.end_time);
const reason = text(input.reason);
const source = text(input.source || 'assistant');
const confirm_block = toBoolean(input.confirm_block);

const errors = [];

function isRealIsoDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;

  const [year, month, day] = value.split('-').map(Number);
  const parsed = new Date(Date.UTC(year, month - 1, day));

  return (
    parsed.getUTCFullYear() === year &&
    parsed.getUTCMonth() === month - 1 &&
    parsed.getUTCDate() === day
  );
}

const isTime = (value) =>
  /^([01]\d|2[0-3]):[0-5]\d$/.test(value);

if (!clinic_name) {
  errors.push({ field: 'clinic_name', message: 'نام کلینیک الزامی است.' });
}

if (!doctor_name) {
  errors.push({ field: 'doctor_name', message: 'نام پزشک الزامی است.' });
}

if (!isRealIsoDate(start_date)) {
  errors.push({
    field: 'start_date',
    message: 'تاریخ شروع باید معتبر و با قالب YYYY-MM-DD باشد.',
  });
}

if (!isTime(start_time)) {
  errors.push({
    field: 'start_time',
    message: 'ساعت شروع باید با قالب HH:MM باشد.',
  });
}

if (!isRealIsoDate(end_date)) {
  errors.push({
    field: 'end_date',
    message: 'تاریخ پایان باید معتبر و با قالب YYYY-MM-DD باشد.',
  });
}

if (!isTime(end_time)) {
  errors.push({
    field: 'end_time',
    message: 'ساعت پایان باید با قالب HH:MM باشد.',
  });
}

if (!reason) {
  errors.push({ field: 'reason', message: 'علت مسدودسازی الزامی است.' });
}

if (reason.length > 500) {
  errors.push({
    field: 'reason',
    message: 'علت مسدودسازی نباید بیشتر از 500 کاراکتر باشد.',
  });
}

if (!['assistant', 'secretary', 'doctor', 'admin'].includes(source)) {
  errors.push({
    field: 'source',
    message: 'source باید assistant، secretary، doctor یا admin باشد.',
  });
}

if (confirm_block !== true) {
  errors.push({
    field: 'confirm_block',
    message: 'مسدودسازی بازه باید به‌صورت صریح تأیید شود.',
  });
}

return [
  {
    json: {
      clinic_name,
      doctor_name,
      start_date,
      start_time,
      end_date,
      end_time,
      reason,
      source,
      confirm_block,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      errors,
    },
  },
];

return [
  {
    json: {
      success: false,
      result: 'invalid_request',
      message: 'اطلاعات درخواست ناقص یا نامعتبر است.',
      affected_appointment_count: 0,
      affected_appointments: [],
      errors: $json.errors ?? [],
    },
  },
];
